// Place near imports/top of file
const ALLOWED_FINN_HOSTS = (process.env.LOA_FINN_ALLOWED_HOSTS ?? '')
  .split(',')
  .map((h) => h.trim())
  .filter(Boolean);

function getFinnBaseUrl(): URL | null {
  const raw = process.env.LOA_FINN_BASE_URL;
  if (!raw) return null;
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return null;
  }
  if (url.username || url.password) return null;
  if (!['http:', 'https:'].includes(url.protocol)) return null;
  if (ALLOWED_FINN_HOSTS.length > 0 && !ALLOWED_FINN_HOSTS.includes(url.hostname)) return null;
  return url;
}
